Status Buzzer::dispatch(uint8_t cmd_id, std::span<const uint8_t> args, Reply &)
{
    switch (cmd_id) {
    case kCmdTone: {
        const auto a = decode_buzzer_tone_args(args);
        if (!a || !fr::cap::valid(*a)) {
            return std::unexpected(Err::invalid_args);
        }
        return tone(*a);
    }
    case kCmdBeep: {
        const auto a = decode_buzzer_beep_args(args);
        if (!a || !fr::cap::valid(*a)) {
            return std::unexpected(Err::invalid_args);
        }
        return beep(*a);
    }
    case kCmdMelody: {
        const auto a = decode_buzzer_melody_args(args);
        if (!a || !fr::cap::valid(*a)) {
            return std::unexpected(Err::invalid_args);
        }
        return melody(*a);
    }
    case kCmdStop: {
        if (!fr::proto::decode_empty(args)) {
            return std::unexpected(Err::invalid_args);
        }
        return stop();
    }
    case kCmdSetVolume: {
        const auto a = decode_buzzer_set_volume_args(args);
        if (!a || !fr::cap::valid(*a)) {
            return std::unexpected(Err::invalid_args);
        }
        return set_volume(*a);
    }
    default:
        return std::unexpected(Err::unsupported);
    }
}

